//! Generate the canonical V1 `CancelAssetLock` positive and negative fixtures.
//!
//! Run with:
//!
//! ```text
//! cargo run -p iroha_data_model --features test-fixtures --bin cancel_asset_lock_fixtures
//! ```
//!
//! Pass `--check` to compare the generated bytes with the checked-in fixture
//! directory without writing it.

use std::{env, error::Error, ffi::OsString, path::PathBuf};

use iroha_data_model::testing::cancel_asset_lock::{
    check_fixtures, default_output_dir, render_fixtures, write_fixtures,
};

#[derive(Debug)]
struct Args {
    output_dir: PathBuf,
    check: bool,
}

fn main() -> Result<(), Box<dyn Error>> {
    let args = parse_args(env::args_os().skip(1))?;
    let fixtures = render_fixtures()?;
    if args.check {
        check_fixtures(&args.output_dir, &fixtures)
    } else {
        write_fixtures(&args.output_dir, &fixtures)
    }
}

fn parse_args(args: impl IntoIterator<Item = OsString>) -> Result<Args, Box<dyn Error>> {
    let mut output_dir = default_output_dir();
    let mut check = false;
    let mut args = args.into_iter();
    while let Some(arg) = args.next() {
        match arg.to_str() {
            Some("--check") => check = true,
            Some("--output-dir") => {
                output_dir = PathBuf::from(args.next().ok_or("`--output-dir` requires a path")?);
            }
            Some("--help" | "-h") => {
                println!(
                    "Usage: cancel_asset_lock_fixtures [--check] [--output-dir PATH]\n\
                     \n\
                     Generate or verify the canonical V1 CancelAssetLock fixtures."
                );
                std::process::exit(0);
            }
            Some(other) => return Err(format!("unrecognized argument `{other}`").into()),
            None => return Err("arguments must be valid UTF-8".into()),
        }
    }
    Ok(Args { output_dir, check })
}
